// Mark key milestones
performance.mark('checkout-start');

// After data fetch
await fetch('/api/checkout');
performance.mark('checkout-data-ready');

// After render
requestAnimationFrame(() => {
  performance.mark('checkout-rendered');

  // Measure from start to render
  performance.measure(
    'checkout-render',
    'checkout-start',
    'checkout-rendered'
  );

  // Measure data fetch duration
  performance.measure(
    'checkout-fetch',
    'checkout-start',
    'checkout-data-ready'
  );
});

// Read results
const measures = performance.getEntriesByType('measure');
for (const m of measures) {
  console.log(`${m.name}: ${m.duration.toFixed(2)}ms`);
}

// Clear when done
performance.clearMarks();
performance.clearMeasures();

// Observe long tasks
const longTaskObserver = new PerformanceObserver((list) => {
  for (const entry of list.getEntries()) {
    console.warn('Long task detected:', entry.duration, 'ms');
    // Send to analytics
    sendToAnalytics({ type: 'longtask', duration: entry.duration });
  }
});
longTaskObserver.observe({ type: 'longtask', buffered: true });

// Observe LCP
const lcpObserver = new PerformanceObserver((list) => {
  const entries = list.getEntries();
  const lastEntry = entries[entries.length - 1];
  console.log('LCP:', lastEntry.renderTime || lastEntry.loadTime);
});
lcpObserver.observe({ type: 'largest-contentful-paint', buffered: true });

// Observe custom marks
const markObserver = new PerformanceObserver((list) => {
  for (const entry of list.getEntries()) {
    console.log('Mark:', entry.name, 'at', entry.startTime);
  }
});
markObserver.observe({ type: 'mark', buffered: true });

// Observe layout shifts
const clsObserver = new PerformanceObserver((list) => {
  for (const entry of list.getEntries()) {
    if (!entry.hadRecentInput) {
      console.log('CLS candidate:', entry.value);
    }
  }
});
clsObserver.observe({ type: 'layout-shift', buffered: true });

const nav = performance.getEntriesByType('navigation')[0];

console.log('DNS lookup:', nav.domainLookupEnd - nav.domainLookupStart);
console.log('TCP connection:', nav.connectEnd - nav.connectStart);
console.log('TLS negotiation:', nav.connectEnd - nav.secureConnectionStart);
console.log('Request sent:', nav.responseStart - nav.requestStart);
console.log('TTFB:', nav.responseStart - nav.requestStart);
console.log('Response download:', nav.responseEnd - nav.responseStart);
console.log('DOM processing:', nav.domInteractive - nav.responseEnd);
console.log('DOM complete:', nav.domContentLoadedEventEnd - nav.domContentLoadedEventStart);
console.log('Full load:', nav.loadEventEnd - nav.loadEventStart);

// Resource timing
const resources = performance.getEntriesByType('resource');
for (const r of resources) {
  console.log(r.name, 'duration:', r.duration.toFixed(2));
}

function CheckoutButton({ onCheckout }) {
  const handleClick = () => {
    performance.mark('checkout-click');

    onCheckout();

    requestAnimationFrame(() => {
      performance.mark('checkout-paint');

      performance.measure(
        'checkout-latency',
        'checkout-click',
        'checkout-paint'
      );
    });
  };

  return <button onClick={handleClick}>Checkout</button>;
}

// Custom hook for repeatable measurements
function useInteractionMeasure(label) {
  useEffect(() => {
    const start = `${label}-start`;
    const end = `${label}-end`;

    return () => {
      if (performance.mark(start) && performance.mark(end)) {
        performance.measure(label, start, end);
      }
    };
  }, [label]);
}
